#if UNITY_EDITOR
using System;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
namespace IanGame.Editor {
// Uses Phase26's isolated save slot and finally-based model restoration.
// Controller/UI integration is deliberately separate from physical keyboard tests.
public static class MasterDirectiveVerification {
 static Action<bool,string> check;static Action<GameObject,string> audit;static LifeWorldController w;static GameManager g;
 static IEnumerator Frames(int n=8){for(int i=0;i<n;i++)yield return null;}
 static void Shot(string name){System.IO.Directory.CreateDirectory("Docs/Phase26/MasterScreenshots");ScreenCapture.CaptureScreenshot("Docs/Phase26/MasterScreenshots/"+name+".png");}
 static IEnumerator Travel(string zone){check(w.Travel(zone),"Travel accepted: "+zone);while(w.Busy)yield return null;yield return Frames();}
 static IEnumerator Use(WorldInteractable target,int action=-2,string food=""){
  Vector2 point=w.Safe(w.CurrentZone,target.Point-g.world.rules.Zone(target.zone).origin);w.Player.Warp(point);w.follow.Snap();yield return Frames();check(w.IsInReach(target),"Physical approach clear: "+target.id);check(w.Begin(target,action,food),"World action accepted: "+target.id+" / "+action);while(w.Busy)yield return null;yield return Frames();
 }
 static WorldInteractable Object(string id)=>w.objects.First(o=>o.id==id);

 public static IEnumerator Capture(LifeWorldController world,GameManager game,Action<bool,string> assertion,Action<GameObject,string> uiAudit){
  w=world;g=game;check=assertion;audit=uiAudit;
  yield return new WaitForSecondsRealtime(.3f);
  var state=g.CaptureState();state.stats.money=5000;state.stats.hunger=70;g.RestoreState(state);g.clock.realtimeEnabled=false;
  check(!Object("fridge").gameObject.activeInHierarchy&&w.GetComponent<StarterHomePresentation>().kitchenFloor.sprite==w.GetComponent<StarterHomePresentation>().woodFloor,"Saved bed-only scene initializes correctly in Play");
  var legacy=g.CaptureState();legacy.economy.housing.starterRevision=0;g.RestoreState(legacy);g.clock.realtimeEnabled=false;yield return Frames();check(Object("fridge").gameObject.activeInHierarchy&&w.GetComponent<StarterHomePresentation>().kitchenFloor.sprite==w.GetComponent<StarterHomePresentation>().legacyFloor,"Legacy load restores furnishings and original floor from bed-only scene");g.RestoreState(state);g.clock.realtimeEnabled=false;yield return Frames();
  var home=w.hud.home;home.Tab(1);w.hud.shell.Push(home.panel);yield return new WaitForSecondsRealtime(.35f);audit(home.panel,"Stable furniture catalog");Shot("04-Furniture-Shop");yield return Frames();
  int index=Array.FindIndex(home.catalog.furniture,f=>f.id=="fridge");home.buy[index].onClick.Invoke();yield return new WaitForSecondsRealtime(.25f);home.accept.onClick.Invoke();yield return new WaitForSecondsRealtime(.25f);home.place[index].onClick.Invoke();yield return new WaitForSecondsRealtime(.35f);
  var editor=w.hud.GetComponent<WorldFurniturePlacement>();check(w.hud.shell.Top==editor.panel&&!home.panel.activeInHierarchy,"Stable placement screen has no overlapping housing panel");audit(editor.panel,"Placement controls");Shot("05-Furniture-Preview");yield return Frames();
  check(!editor.PreviewAt(new Vector2(0,-3.75f)),"Preview marks obstructed doorway invalid");editor.Confirm();check(g.economy.Housing.placed.Count==0,"Invalid ghost confirmation cannot place or charge");
  check(editor.PreviewAt(new Vector2(4.5f,1.25f)),"Preview accepts a free grid cell outside recommended preset");editor.Confirm();yield return new WaitForSecondsRealtime(.3f);check(g.economy.Housing.placed.Any(p=>p.id=="fridge"&&Vector2.Distance(p.position*2,new Vector2(4.5f,1.25f))<.01f),"Chosen grid position is committed from actual preview");
  home.Tab(1);w.hud.shell.Push(home.panel);yield return new WaitForSecondsRealtime(.2f);check(editor.Begin("fridge"),"Begin free rearrangement");yield return new WaitForSecondsRealtime(.25f);check(editor.PreviewAt(new Vector2(3.5f,1.25f)),"Rearrangement preview accepts another accessible cell");editor.Cancel();yield return new WaitForSecondsRealtime(.25f);check(g.economy.Housing.placed.Any(p=>p.id=="fridge"&&p.position==new Vector2(4.5f,1.25f)/2),"Cancel restores the previous placement without cost");
 }
 public static IEnumerator Run(LifeWorldController world,GameManager game,Action<bool,string> assertion,Action<GameObject,string> uiAudit){
  w=world;g=game;check=assertion;audit=uiAudit;g.world.rules.activityAnimationScale=.12f;g.clock.realtimeEnabled=false;
  var h=g.economy.Housing;check(h.starterRevision==1&&h.owned.SequenceEqual(new[]{"basic-bed"})&&h.placed.Count==0,"New game owns only one bed and no optional furniture");
  check(w.objects.Where(o=>o.zone=="home"&&StarterHomePresentation.Optional(o.id)).All(o=>!o.gameObject.activeInHierarchy),"All furnished-home interaction objects are absent in new life");
  var presentation=w.GetComponent<StarterHomePresentation>();check(presentation!=null&&presentation.optionalDecorations.All(o=>!o.activeInHierarchy),"No free rugs, plants, shelves or decorative furniture");check(presentation.kitchenFloor.sprite==presentation.woodFloor&&presentation.kitchenWall.sprite==presentation.whiteWall,"Starter wood flooring and white wallpaper are actually rendered");
  string why;check(g.economy.housingCatalog.placementPlan.ValidateAccess(h,out why),"Bed and both door approaches connected: "+why);
  foreach(var id in new[]{"fridge","basic-table","desk","sofa"})check(!g.economy.CanBuyFurniture(id,out why),"Zero cash refuses purchase without debt: "+id);
  check(g.SaveAutomaticCheckpoint(out why),"Save initial starter home");SaveData born;check(g.saves.TryReadAutomatic(out born,out why)&&born.birthIntroCompleted,"DAY 1 close persists in real save");g.RestoreState(born);g.clock.realtimeEnabled=false;yield return Frames();check(!g.BirthIntroductionPending&&!w.hud.GetComponent<BirthIntroductionPopup>().IsShowing,"Loading acknowledged birth does not reopen popup");
  Shot("01-Starter-1280x720");yield return Frames();CommercialSliceVerification.SetSize(1920,1080);yield return Frames(12);Shot("02-Starter-1920x1080");yield return Frames();audit(w.hud.gameObject,"Starter HUD 1080p");CommercialSliceVerification.SetSize(1280,720);yield return Frames(12);
  var old=g.CaptureState();old.economy.housing.starterRevision=0;old.economy.housing.owned.Add("bookshelf");g.RestoreState(old);g.clock.realtimeEnabled=false;yield return Frames();check(Object("fridge").gameObject.activeInHierarchy&&Object("meal-table").gameObject.activeInHierarchy&&g.economy.Housing.owned.Contains("bookshelf"),"Legacy furnished home and owned furniture remain intact");g.RestoreState(born);g.clock.realtimeEnabled=false;yield return Frames();check(!Object("fridge").gameObject.activeInHierarchy,"Returning to new save restores bed-only state");
  yield return Travel("bathroom");check(new[]{"sink","shower","toilet"}.All(id=>Object(id).zone=="bathroom"&&Object(id).isActiveAndEnabled),"Independent bathroom retains all fixed hygiene installations");var hygiene=g.world.State.hygiene;yield return Use(Object("shower"));check(g.world.State.hygiene>=hygiene,"Shower updates persistent hygiene");Shot("03-Jade-Bathroom");yield return Frames();yield return Travel("shop");
  long cash=g.economy.Cash;double elapsed=g.clock.ElapsedSeconds;yield return Use(Object("counter"),-3);check(g.economy.Cash==cash+g.world.rules.neighbourhoodHelpReward&&Math.Abs(g.clock.ElapsedSeconds-elapsed-g.world.rules.neighbourhoodHelpMinutes*60)<.01,"Starter can earn real wallet income through shop activity with exact time cost");
  int bread=g.world.State.bread;yield return Use(Object("counter"),3,"bread");check(g.world.State.bread==bread-1,"Eating at public counter works without any home furniture");
  var fixture=g.CaptureState();fixture.stats.money=25000;fixture.progression.age=30;fixture.stats.energy=85;fixture.stats.hunger=70;fixture.stats.social=50;fixture.stats.knowledge=50;g.RestoreState(fixture);g.clock.realtimeEnabled=false;
  yield return Travel("home");w.Player.Warp(new Vector2(0,-2.9f));yield return Frames();
  foreach(var rule in g.economy.housingCatalog.placementPlan.furniture){Vector2 position;check(g.economy.housingCatalog.placementPlan.Find(rule.id,g.economy.Housing,null,out position,out why),"Reachable recommended position for "+rule.id+" / "+why);}
  var home=w.hud.home;home.Tab(1);w.hud.shell.Push(home.panel);yield return Frames();Shot("04-Furniture-Shop");yield return Frames();audit(home.panel,"Furniture shop expanded catalog");int index=Array.FindIndex(home.catalog.furniture,f=>f.id=="fridge");cash=g.economy.Cash;home.buy[index].onClick.Invoke();yield return Frames();home.accept.onClick.Invoke();yield return Frames();check(g.economy.Cash==cash-home.catalog.Furniture("fridge").price&&g.economy.Housing.owned.Contains("fridge"),"Actual purchase confirmation charges catalog price and grants ownership");check(!g.economy.BuyFurniture(Guid.NewGuid().ToString("N"),"fridge"),"Duplicate furniture purchase cannot charge twice");
  home.place[index].onClick.Invoke();yield return Frames();var editor=w.hud.GetComponent<WorldFurniturePlacement>();check(editor!=null&&w.hud.shell.Top==editor.panel&&!w.CanControl,"Placement preview opens and blocks movement");Shot("05-Furniture-Preview");yield return new WaitForSecondsRealtime(.3f);cash=g.economy.Cash;editor.Confirm();yield return Frames();check(g.economy.Housing.placed.Any(p=>p.id=="fridge")&&g.economy.Cash==cash,"Preview confirmation places owned furniture free of charge");
  check(!g.economy.PlaceFurniture("fridge",new Vector2(0,-1.875f)),"Door obstruction rejected without moving owned furniture");check(!g.economy.PlaceFurniture("sofa",new Vector2(0,-1)),"Unowned furniture cannot be placed");
  foreach(var id in new[]{"basic-table","desk","sofa","bookshelf"}){check(g.economy.BuyFurniture(Guid.NewGuid().ToString("N"),id),"Paid purchase: "+id);yield return Frames();check(g.economy.FindFurniturePlacement(id,false,out var p,out why),"Owned item can be placed: "+id+" / "+why);check(g.economy.PlaceFurniture(id,p),"Free valid placement: "+id);yield return Frames();}
  check(GameObject.Find("Owned furniture / fridge").GetComponent<WorldInteractable>().kind==WorldInteractionKind.Fridge&&GameObject.Find("Owned furniture / basic-table").GetComponent<WorldInteractable>().kind==WorldInteractionKind.Meal,"Purchased fridge and dining table have real life functions");
  yield return Use(GameObject.Find("Owned furniture / fridge").GetComponent<WorldInteractable>(),-1,"rice");yield return Use(GameObject.Find("Owned furniture / basic-table").GetComponent<WorldInteractable>());Shot("06-Furnished-By-Purchases");yield return Frames();
  check(g.SaveAutomaticCheckpoint(out why),"Save paid and placed home");SaveData paid;check(g.saves.TryReadAutomatic(out paid,out why),"Read paid home from disk");int placed=g.economy.Housing.placed.Count;cash=g.economy.Cash;g.RestoreState(paid);g.clock.realtimeEnabled=false;yield return Frames();check(g.economy.Cash==cash&&g.economy.Housing.placed.Count==placed&&g.economy.Housing.starterRevision==1,"Load preserves money, starter revision, ownership and placements");
  var moving=g.CaptureState();moving.stats.money=0;g.RestoreState(moving);g.clock.realtimeEnabled=false;check(!g.economy.MoveResidence(Guid.NewGuid().ToString("N"),"improved"),"Insufficient funds refuse moving");g.RestoreState(paid);g.clock.realtimeEnabled=false;var owned=g.economy.Housing.owned.ToArray();cash=g.economy.Cash;check(g.economy.MoveResidence(Guid.NewGuid().ToString("N"),"improved"),"Paid residence move succeeds");yield return Frames();check(g.economy.Cash==cash-home.catalog.Residence("improved").movingCost&&g.economy.Housing.owned.SequenceEqual(owned)&&g.economy.Housing.placed.Count==0,"Moving charges once, keeps every owned item and stores furniture");g.RestoreState(paid);g.clock.realtimeEnabled=false;yield return Frames();
  home.Tab(1);w.hud.shell.Push(home.panel);yield return Frames();check(editor.Begin("bookshelf"),"Begin reposition of owned bookshelf");yield return Frames();editor.Cancel();yield return Frames();check(g.economy.Housing.placed.Count==placed&&w.CanControl,"Cancel leaves placements unchanged and restores control");
  foreach(int n in new[]{0,1,4}){w.hud.navigation.Open(n);yield return new WaitForSecondsRealtime(.2f);audit(w.hud.navigation.panels[n],"Major panel "+n);Shot(n==0?"07-Life":n==1?"08-Character-Growth":"09-Missions");yield return Frames();}while(w.hud.shell.Depth>0)w.hud.shell.Pop();w.hud.GetComponent<UINavigationService>().Inventory();yield return Frames();Shot("10-Inventory");yield return Frames();while(w.hud.shell.Depth>0)w.hud.shell.Pop();
  yield return Travel("workplace");var work=g.CaptureState();work.phase23.employment.currentJobId="convenience";work.time.subDaySeconds=9*3600;g.RestoreState(work);g.clock.realtimeEnabled=false;yield return Frames();Shot("11-Workplace");yield return Frames();cash=g.economy.Cash;int count=g.phase23.Progress.employment.workCount;yield return Use(Object("workdesk"),0);check(g.economy.Cash>cash&&g.phase23.Progress.employment.workCount==count+1,"Existing paid job creates exactly one work record and salary");check(!g.CanPerformAction(0,out why),"Duplicate same-day shift refused");
  var npc=w.objects.First(o=>o.npcId=="colleague");w.Player.Warp(npc.Point);yield return Frames();check(w.Use(npc),"NPC dialogue panel opens");yield return Frames();Shot("12-NPC-Dialogue");yield return Frames();int history=g.phase23.Progress.social.history.Count;w.hud.choices.GetComponentsInChildren<Button>().First(b=>b.gameObject.activeInHierarchy).onClick.Invoke();while(w.Busy)yield return null;yield return Frames();check(g.phase23.Progress.social.history.Count==history+1,"NPC conversation updates existing relationship history");
  yield return Travel("city");g.clock.Restore(g.clock.Day,new TimeSnapshot{subDaySeconds=12*3600,elapsedSeconds=g.clock.ElapsedSeconds});w.Player.Warp(w.CurrentZone.origin+new Vector2(0,1.5f));w.follow.Snap();yield return Frames();var street=w.GetComponentInChildren<WorldStreetLife>();check(street!=null&&street.vehicles.Length==4&&street.pedestrians.Length==10,"Living city has ten pedestrians and four traffic vehicles");
  var starts=street.vehicles.Select(v=>v.body.position).ToArray();var moved=new bool[starts.Length];var signals=new HashSet<Sprite>();var frames=new HashSet<Sprite>();float until=Time.unscaledTime+27;bool stopped=false;
  while(Time.unscaledTime<until){for(int i=0;i<starts.Length;i++)moved[i]|=Vector2.Distance(starts[i],street.vehicles[i].body.position)>1;if(street.signal!=null)signals.Add(street.signal.sprite);foreach(var p in street.pedestrians)if(p.visual.enabled)frames.Add(p.visual.sprite);stopped|=!street.VehicleGreen&&street.vehicles.Any(v=>v.velocity<.01f);yield return null;}
  check(moved.All(x=>x),"Every real traffic body moves during observed cycle");check(signals.Count==3&&stopped,"Traffic signals cycle through three states and vehicles stop");if(street.residentSimulation){var residents=w.GetComponent<WorldNPCScheduler>();residents.Capture();check(g.world.State.residents.Count==12&&g.world.State.residents.Any(n=>n.action==NPCDailyAction.Eat&&n.zone=="shop"),"Noon residents follow indoor lunch schedules instead of forced street population");}else check(frames.Count>=12,"Live pedestrians advance distinct walk frames");Shot("13-City-Day");yield return Frames();g.clock.Restore(g.clock.Day,new TimeSnapshot{subDaySeconds=23*3600+50*60,elapsedSeconds=g.clock.ElapsedSeconds});yield return new WaitForSecondsRealtime(.4f);if(street.residentSimulation){w.GetComponent<WorldNPCScheduler>().Capture();check(g.world.State.residents.Count(n=>n.action==NPCDailyAction.Sleep)>=6&&street.vehicles.Count(v=>v.body.simulated)==2,"Night residents return home on their individual schedules and traffic reduces");}else check(street.pedestrians.Count(p=>p.visual.enabled)==3&&street.vehicles.Count(v=>v.body.simulated)==2,"Night changes population and vehicle activity");Shot("14-City-Night");yield return Frames();
  yield return Travel("home");int day=g.clock.Day;yield return Use(Object("bed"));check(g.clock.Day==day+1&&g.world.Hour==7&&w.CanControl,"Return home, sleep eight hours and wake exactly next day with control");Shot("15-Next-Morning");yield return Frames();
 }
}
}
